-- 6. Indexes
CREATE INDEX idx_ac_races_race_id ON public.ac_races (race_id);
CREATE INDEX idx_ac_races_sources ON public.ac_races USING GIN (sources);
CREATE INDEX idx_ac_races_display_order ON public.ac_races (display_order);
CREATE INDEX idx_ac_subraces_race_id ON public.ac_subraces (race_id);
CREATE INDEX idx_ac_subraces_check_id ON public.ac_subraces (check_id);
CREATE INDEX idx_ac_subraces_sources ON public.ac_subraces USING GIN (sources);
CREATE INDEX idx_ac_subraces_display_order ON public.ac_subraces (display_order);

-- 7. Updated_at triggers
DROP TRIGGER IF EXISTS set_updated_at ON public.ac_races;
CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.ac_races FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();
DROP TRIGGER IF EXISTS set_updated_at ON public.ac_subraces;
CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.ac_subraces FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

-- 8. Row Level Security (RLS)
ALTER TABLE public.ac_races ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public read access to ac_races" ON public.ac_races FOR SELECT USING (true);
CREATE POLICY "Allow service_role to manage ac_races" ON public.ac_races FOR ALL TO service_role USING (true) WITH CHECK (true);

ALTER TABLE public.ac_subraces ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public read access to ac_subraces" ON public.ac_subraces FOR SELECT USING (true);
CREATE POLICY "Allow service_role to manage ac_subraces" ON public.ac_subraces FOR ALL TO service_role USING (true) WITH CHECK (true);

-- 9. Backward-compatibility view: v_ac_races
CREATE OR REPLACE VIEW public.v_ac_races AS
SELECT
    s.id,
    r.name AS race,
    r.name,
    s.subrace,
    s.size,
    s.speed,
    s.language,
    s.str,
    s.dex,
    s.con,
    s.int_stat,
    s.wis,
    s.cha,
    s.extra,
    array_to_string(s.sources, ', ') AS source,
    s.sources,
    s.notes_advice,
    s.notes_advice AS rage_advice,
    s.check_id,
    s.display_order,
    s.created_at,
    s.updated_at
FROM public.ac_subraces s
JOIN public.ac_races r ON s.race_id = r.race_id;